{
  "item_id": "PRISMA_2020_1",
  "elements": [
    {
      "element_id": "prisma_2020_1_e1",
      "status": "PRESENT",
      "chunk_id": "text_2",
      "quote": "Should my child be given antibiotics? A systematic review of parental decision making in rural and remote locations",
      "reason": "The title explicitly includes the phrase \"A systematic review\"."
    },
    {
      "element_id": "prisma_2020_1_e2",
      "status": "PRESENT",
      "chunk_id": "text_2",
      "quote": "Should my child be given antibiotics? A systematic review of parental decision making in rural and remote locations",
      "reason": "The title identifies the population (\"parental\") and the exposure/intervention (\"antibiotics\") in the context of the review question."
    },
    {
      "element_id": "prisma_2020_1_e3",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "The title does not contain supplementary information such as study design or update status, and this element is conditional; it is not required if the information is not present in the title."
    }
  ],
  "confidence": 100
}

{
  "item_id": "PRISMA_2020_3",
  "elements": [
    {
      "element_id": "prisma_2020_3_e1",
      "status": "PRESENT",
      "chunk_id": "text_2",
      "quote": "The emergence and growth in antibiotic resistant bacteria is a critical public health problem exacerbated by the misuse of antibiotics. Children frequently succumb to illness and are often treated with antibiotic medicines which may be used improperly by the parent. There is limited evidence of the factors influencing parental decision-making about the use of antibiotics in low-resource contexts.",
      "reason": "The text describes the current state of knowledge regarding antibiotic resistance and misuse, and identifies the uncertainty/gap regarding factors influencing parental decision-making in low-resource contexts."
    },
    {
      "element_id": "prisma_2020_3_e2",
      "status": "PRESENT",
      "chunk_id": "text_2",
      "quote": "The aim of this systematic review was to understand and describe how parents living in rural and remote locations make choices about their children's antibiotic use.",
      "reason": "The review's aim is clearly stated, and the context provided in the background (the problem of antibiotic misuse and limited evidence in this specific population) establishes the need for the review."
    },
    {
      "element_id": "prisma_2020_3_e3",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "The manuscript does not mention the existence of similar systematic reviews, so this conditional requirement does not apply."
    },
    {
      "element_id": "prisma_2020_3_e4",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "This is not a review of intervention effects; it is a review of parental decision-making factors."
    },
    {
      "element_id": "prisma_2020_3_e5",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "The review does not involve a complex intervention or delivery context requiring a logic model."
    }
  ],
  "confidence": 100
}

{
  "item_id": "PRISMA_2020_4",
  "elements": [
    {
      "element_id": "prisma_2020_4_e1",
      "status": "PRESENT",
      "chunk_id": "text_3",
      "quote": "Thus, the objective of this review was to systematically describe the decision-making process of rural parents regarding their use of antibiotics. We sought to address the following research question: What factors influence the decisions of parents with children living in rural and remote locations in their use of antibiotics?",
      "reason": "The manuscript explicitly states both the objective and the research question."
    },
    {
      "element_id": "prisma_2020_4_e2",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "The review is not a review of intervention effects (it is a descriptive review of decision-making processes), therefore planned comparisons using PICO are not applicable."
    }
  ],
  "confidence": 100
}

{
  "item_id": "PRISMA_2020_5",
  "elements": [
    {
      "element_id": "prisma_2020_5_e1",
      "status": "PRESENT",
      "chunk_id": "text_5",
      "quote": "Studies were eligible if they provided data on the decision-making process of parents living in rural and remote locations in their use of antibiotics with their children (aged 0-18 years). ... We considered quantitative and qualitative designs, mixed methods, observational, prospective, systematic reviews, crosssectional and longitudinal studies.",
      "reason": "The manuscript specifies the population (parents of children aged 0-18), the setting (rural and remote), the topic (decision-making process regarding antibiotic use), and the eligible study designs."
    },
    {
      "element_id": "prisma_2020_5_e2",
      "status": "PRESENT",
      "chunk_id": "text_5",
      "quote": "Worldwide studies available in English were included, and no restrictions were placed on the publication period. Both peerreviewed and grey literature were accepted.",
      "reason": "The manuscript specifies the language (English), publication period (no restrictions), and publication status (peer-reviewed and grey literature) eligibility criteria."
    },
    {
      "element_id": "prisma_2020_5_e3",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "The manuscript lists reasons for exclusion (e.g., participant characteristics, lack of exclusive results, lack of data on decision-making), but it does not explicitly distinguish between studies excluded because outcomes were not measured versus studies excluded because outcome results were not reported."
    },
    {
      "element_id": "prisma_2020_5_e4",
      "status": "PRESENT",
      "chunk_id": "text_9",
      "quote": "Primary findings were categorised into groups for the synthesis: (1) the process of decision-making to use or not use antibiotics i.e., influences on antibiotic use (2) factors contributing to specific behaviours with antibiotics identified i.e., non-prescription use of antibiotics, non-adherence to antibiotic treatment, requests for antibiotic prescriptions.",
      "reason": "The manuscript specifies the groups used for synthesis and links them to the review objectives."
    },
    {
      "element_id": "prisma_2020_5_e5",
      "status": "PRESENT",
      "chunk_id": "text_8",
      "quote": "Inclusion of studies scoring low on JBI may jeopardise the validity of the review findings [23]. Thus, only studies reaching 60% or higher 'yes' results after discrepancies between reviewers had been resolved were included in the review.",
      "reason": "The manuscript provides a rationale for the restriction on study eligibility based on JBI quality assessment scores."
    }
  ],
  "confidence": 100
}

{
  "item_id": "PRISMA_2020_6",
  "elements": [
    {
      "element_id": "prisma_2020_6_e1",
      "status": "PRESENT",
      "chunk_id": "text_7",
      "quote": "The search was performed from 31 January 2023 and monitored weekly through database alerts until 28 June 2023.",
      "reason": "The text specifies the search period for the electronic databases. Additionally, chunk text_4 notes that grey literature searches were conducted between 3 and 22 March 2023."
    },
    {
      "element_id": "prisma_2020_6_e2",
      "status": "PARTIAL",
      "chunk_id": "text_7",
      "quote": "Five electronic databases were systematically searched: Web of Science; Scopus; EBSCOhost databases (Academic Search Premier, CINAHL and Medline).",
      "reason": "The names of the databases are provided. However, the search interface/platform (other than mentioning EBSCOhost for some) and the available coverage dates for each database are not reported."
    },
    {
      "element_id": "prisma_2020_6_e3",
      "status": "PRESENT",
      "chunk_id": "text_4",
      "quote": "A pre-defined research protocol was registered with the International Prospective Register of Systematic Reviews (PROSPERO) prior to the commencement of the review.",
      "reason": "The study register (PROSPERO) is named. While specific date restrictions for the register search are not explicitly detailed, the context implies the search was for the review itself."
    },
    {
      "element_id": "prisma_2020_6_e4",
      "status": "PARTIAL",
      "chunk_id": "text_4",
      "quote": "Grey literature covered both accessible and inaccessible articles and included searching: Trove; Open Grey; OpenDOAR; NZresearch.org.nz; MedNar; Western Pacific Region Index Medicus; Clinical Trials Search Portal; Theses Canada; PsycINFO; and Google Scholar.",
      "reason": "The names of the grey literature sources are provided, but the URLs for these sources are not included."
    },
    {
      "element_id": "prisma_2020_6_e5",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "There is no evidence that organizations or manufacturers were contacted to identify studies."
    },
    {
      "element_id": "prisma_2020_6_e6",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "There is no evidence that individuals were contacted to identify studies."
    },
    {
      "element_id": "prisma_2020_6_e7",
      "status": "PRESENT",
      "chunk_id": "text_4",
      "quote": "To identify additional articles, the reference lists of studies eligible for fulltext review and grey literature websites/search engines, were searched between 3 and 22 March 2023.",
      "reason": "The text specifies that reference lists of studies eligible for full-text review were examined."
    },
    {
      "element_id": "prisma_2020_6_e8",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "The manuscript does not report performing backward or forward citation searching as a distinct method, other than mentioning reference lists."
    },
    {
      "element_id": "prisma_2020_6_e9",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "There is no evidence that specific journals or conference proceedings were hand-searched."
    }
  ],
  "confidence": 95
}

