{
  "item_id": "PRISMA_2020_8",
  "elements": [
    {
      "element_id": "prisma_2020_8_e1",
      "status": "PRESENT",
      "chunk_id": "text_6",
      "quote": "The titles and abstracts of records were screened by SM using a pre-defined decision tree... Fidelity checks were conducted by the other reviewers (MB and SP) on a random selection (10%) of included and excluded records... Articles included in the next stage, underwent full-text evaluation by SM using a fulltext decision tree tool to assess study eligibility... A random sample (10%) of full-text articles were reviewed by (MB and SP) to check decisions against the decision tree criteria.",
      "reason": "The text specifies that the principal reviewer (SM) performed the initial screening of titles/abstracts and full-text articles, with fidelity checks performed by two other reviewers (MB and SP) on a 10% sample."
    },
    {
      "element_id": "prisma_2020_8_e2",
      "status": "PRESENT",
      "chunk_id": "text_6",
      "quote": "The titles and abstracts of records were screened by SM... Fidelity checks were conducted by the other reviewers (MB and SP) on a random selection (10%) of included and excluded records... Articles included in the next stage, underwent full-text evaluation by SM... A random sample (10%) of full-text articles were reviewed by (MB and SP) to check decisions against the decision tree criteria.",
      "reason": "The text indicates that screening was primarily performed by one reviewer (SM) with a 10% check by others, rather than independent dual screening of all records."
    },
    {
      "element_id": "prisma_2020_8_e3",
      "status": "PRESENT",
      "chunk_id": "text_6",
      "quote": "Discrepancies were resolved through team discussion, or referred to the third reviewer to determine study inclusion... Inconsistencies in opinion were discussed until a consensus was reached, or when there was disagreement, the third reviewer made the final decision regarding study inclusion.",
