    },
    {
      "element_id": "prisma_2020_8_e4",
      "status": "PRESENT",
      "chunk_id": "text_6",
      "quote": "During screening, one study investigator was emailed to confirm participant characteristics, to no avail.",
      "reason": "The text mentions an attempt to contact a study investigator to confirm eligibility information."
