  "elements": [
    {
      "element_id": "prisma_2020_9_e1",
      "status": "PRESENT",
      "chunk_id": "text_8",
      "quote": "The initial extraction was performed by one reviewer (SM) and re-checked for accuracy. Subsequently, two other members of the research team (MB and SP) crossed-checked the extracted data.",
