{
  "item_id": "PRISMA_2020_10a",
  "elements": [
    {
      "element_id": "prisma_2020_10a_e1",
      "status": "PRESENT",
      "chunk_id": "text_8",
      "quote": "The primary outcome of interest was: the drivers/determinants of parents' decisions towards the use of antibiotics with their children. Variables investigated included factors predisposing parents to use antibiotics (factors associated with use), and determinants of how antibiotics were accessed and used by parents (i.e., prescription/non-prescription use, asking prescribers for antibiotics, and antibiotic adherence behaviour). We considered any measure of parental decision-making, which was predominantly self-report.",
      "reason": "The authors explicitly define the primary outcome (drivers/determinants of parental decisions) and list the variables/domains investigated (factors predisposing to use, access, and adherence)."
    },
    {
      "element_id": "prisma_2020_10a_e2",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "The manuscript does not specify the time frame of measurement for the outcome domains (e.g., whether they sought data on specific time points or durations)."
    },
    {
      "element_id": "prisma_2020_10a_e3",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "The manuscript does not state whether all results compatible with the outcome domains were sought from the included studies."
    },
    {
      "element_id": "prisma_2020_10a_e4",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "As the authors did not specify whether they sought all compatible results (e10a_e3), this conditional requirement is not applicable based on the provided text."
    },
    {
      "element_id": "prisma_2020_10a_e5",
      "status": "PRESENT",
      "chunk_id": "text_4",
      "quote": "No amendments were made to the protocol during the review process.",
      "reason": "The authors explicitly state that no amendments were made to the protocol, implying no changes to outcome-domain inclusion or definitions."
    },
    {
      "element_id": "prisma_2020_10a_e6",
      "status": "PRESENT",
      "chunk_id": "text_4",
      "quote": "No amendments were made to the protocol during the review process.",
      "reason": "The authors state no amendments were made to the protocol, implying no changes to the processes for selecting results."
    },
    {
      "element_id": "prisma_2020_10a_e7",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "The manuscript does not explicitly report which outcomes were considered most important for interpreting conclusions or provide a rationale for prioritization."
    }
  ],
  "confidence": 95
}

{
  "item_id": "PRISMA_2020_10b",
  "elements": [
    {
      "element_id": "prisma_2020_10b_e1",
      "status": "PRESENT",
      "chunk_id": "text_8",
      "quote": "The following pre-specified data was collected from each eligible study, similar to the information extracted in prior reviews [4]: author name; year of publication; country; study aim; study setting/context; participant information (caregiver and child characteristics); study design and methodology; key findings (principal outcomes and results relevant to the current research); and study limitations. The primary outcome of interest was: the drivers/determinants of parents' decisions towards the use of antibiotics with their children. Variables investigated included factors predisposing parents to use antibiotics (factors associated with use), and determinants of how antibiotics were accessed and used by parents (i.e., prescription/non-prescription use, asking prescribers for antibiotics, and antibiotic adherence behaviour).",
      "reason": "The authors explicitly list the variables for which data were sought, including study characteristics (author, year, country, etc.) and specific variables related to the research question (drivers/determinants of antibiotic use, access, and adherence)."
    },
    {
      "element_id": "prisma_2020_10b_e2",
      "status": "PRESENT",
      "chunk_id": "text_8",
      "quote": "In one study, participants were described as 'parents/carers of young children' and the age range of the children was not specified [20]. However, we included this study based on the assumption that 'young children' was the same as pre-adolescents (primary school age and younger), given that parents were recruited through early childhood education services and playgroups.",
      "reason": "The authors describe a specific assumption made regarding missing information (the age range of children in one study) to justify its inclusion."
    },
    {
      "element_id": "prisma_2020_10b_e3",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "The criterion asks for any tool used to determine which data items to collect. The text states that data collection was based on a \"standardised format\" and \"similar to the information extracted in prior reviews [4]\", but does not indicate that a specific, formal tool (like a standardized data extraction form template from a specific organization) was used to determine the data items themselves, other than the review team's pre-specification."
    }
  ],
  "confidence": 100
}

{
  "item_id": "PRISMA_2020_11",
  "elements": [
    {
      "element_id": "prisma_2020_11_e1",
      "status": "PRESENT",
      "chunk_id": "text_10",
      "quote": "We assessed the possibility of bias and the methodological quality of studies included in the next phase of the review, using the Joanna Briggs Institute (JBI) critical appraisal checklists.",
      "reason": "The authors specify the use of Joanna Briggs Institute (JBI) critical appraisal checklists for assessing risk of bias."
    },
    {
      "element_id": "prisma_2020_11_e2",
      "status": "PRESENT",
      "chunk_id": "text_10",
      "quote": "The JBI tools were selected according to the design of each study assessed, and all items in the corresponding checklists were utilised. Subsequently, we employed the following four JBI checklists: studies reporting prevalence data; qualitative research; cohort studies; and analytical cross-sectional studies.",
      "reason": "The authors specify that they used JBI checklists corresponding to the study designs (prevalence, qualitative, cohort, analytical cross-sectional) and that all items in those checklists were utilized."
    },
    {
      "element_id": "prisma_2020_11_e3",
      "status": "PRESENT",
      "chunk_id": "text_8",
      "quote": "We used the following score ranges to rate the potential risk of bias of individual studies: low risk of bias for studies achieving 70% or more 'yes' scores; moderate risk of bias for studies obtaining between 50 and 69% 'yes' scores (noting studies below 60% were excluded); and high risk of bias if the number of 'yes' scores was below 50% [25].",
      "reason": "The authors report the rules used to derive an overall risk-of-bias judgment (low, moderate, high) based on percentage scores."
    },
    {
      "element_id": "prisma_2020_11_e4",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "The authors used standard JBI checklists and did not report making adaptations to them."
    },
    {
      "element_id": "prisma_2020_11_e5",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "The authors used existing JBI tools, not a newly developed tool."
    },
    {
      "element_id": "prisma_2020_11_e6",
      "status": "PRESENT",
      "chunk_id": "text_10",
      "quote": "Two reviewers (SM and SP) independently assessed full-text studies (i.e., appraisals were performed by the principal reviewer and checked by SP). A proportion (10%) of randomly selected studies were assessed by the third reviewer (MB) using the JBI tools. ... Discrepancies in appraisals were managed through discussion between the reviewers to reach agreement.",
      "reason": "The authors report the number of reviewers (two primary, one third for 10% sample), their independence (independent assessment), and the process for resolving disagreements (discussion)."
    },
